from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
left = Motor(Port.C, Direction.COUNTERCLOCKWISE)
right = Motor(Port.D, Direction.CLOCKWISE)
front_moter = Motor(Port.E, Direction.CLOCKWISE)
back_moter = Motor(Port.A, Direction.CLOCKWISE)
colorSensorR = ColorSensor(Port.B)
colorSensorL = ColorSensor(Port.F)
drive_base = DriveBase(left, right, 61, 152)

async def main():
    drive_base.use_gyro(True)
    await prime_hub.speaker.beep(500, 100)
    await prime_hub.speaker.beep(200, 100)
    drive_base.settings(straight_speed=250)
    await drive_base.straight(550, then=Stop.NONE)
    await drive_base.turn(-65, then=Stop.NONE)
    await drive_base.straight(450, then=Stop.NONE)
    await drive_base.turn(110, then=Stop.NONE)
    drive_base.settings(straight_speed=65)
    await drive_base.straight(100, then=Stop.NONE)
    await drive_base.turn(-160, then=Stop.NONE)
    drive_base.settings(straight_speed=200)
    await drive_base.straight(100)
    await back_moter.run_angle(500, -225)
    await drive_base.straight(-100)
    await back_moter.run_angle(999, 290)
    await drive_base.straight(-25)
    await drive_base.turn(-100)
    await drive_base.straight(750)


run_task(main())